import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.BDKIrnCI.js";const g=JSON.parse('{"title":"Creating a plugin","description":"","frontmatter":{},"headers":[],"relativePath":"guides/creating-a-plugin.md","filePath":"docs/creating-a-plugin.md"}'),n={name:"guides/creating-a-plugin.md"};function o(d,e,r,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="creating-a-plugin" tabindex="-1">Creating a plugin <a class="header-anchor" href="#creating-a-plugin" aria-label="Permalink to &quot;Creating a plugin&quot;">​</a></h1><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen</span></span></code></pre></div><p>This runs the <code>plugin</code> generator (a <a href="https://turborepo.dev/docs/guides/generating-code" target="_blank" rel="noreferrer">Turborepo generator</a>, defined in <code>turbo/generators/</code>). It asks for three things:</p><table tabindex="0"><thead><tr><th>Prompt</th><th>Example</th><th>Used for</th></tr></thead><tbody><tr><td>Folder name</td><td><code>my-plugin</code></td><td><code>packages/my-plugin/</code>, the npm package name, the release tag prefix and the <code>.wasm</code> file name. Kebab-case, and the folder must not exist yet.</td></tr><tr><td>Plugin name</td><td><code>MyPlugin</code></td><td>The name Pumpkin shows and the data folder name (<code>plugins/data/MyPlugin/</code>). PascalCase. Defaults to the folder name converted.</td></tr><tr><td>Description</td><td><code>Does a thing</code></td><td>The plugin&#39;s metadata, its README, its <code>package.json</code> and the package table in the root README. At most 70 characters, since it is also the package description; <code>src/info.ts</code> can say more later.</td></tr></tbody></table><p>To skip the prompts, pass the answers in that order:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --args</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MyPlugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Does a thing&quot;</span></span></code></pre></div><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><ol><li>Creates <code>packages/&lt;folder&gt;/</code> with a working plugin: <code>package.json</code>, <code>tsconfig.json</code>, <code>vitest.config.ts</code>, <code>src/info.ts</code>, <code>src/plugin.ts</code>, a barebones <code>README.md</code> (a title and the generated blocks) and an integration test that loads the built plugin on a real Pumpkin server.</li><li>Registers the plugin for releases: an entry in <code>release-please-config.json</code> (with <code>&quot;release-as&quot;: &quot;0.0.1&quot;</code>) and one in <code>.release-please-manifest.json</code>, with the plugin starting at version <code>0.0.0</code>, so that its first release is <code>0.0.1</code>. The <code>package.json</code> comes with the license, author, repository and funding metadata every package has. CI fails if a plugin isn&#39;t registered or its metadata is incomplete (<code>pnpm check</code>). See <a href="./ci-and-releases#registering-a-plugin-for-releases">Registering a plugin for releases</a>.</li><li>Runs <code>pnpm install</code>, fills in the plugin&#39;s README from its <code>info.ts</code>, and adds the plugin to the package table in the root README.</li><li>Formats the new files with Biome.</li></ol><p>It doesn&#39;t commit anything. A CI job (<code>🧬 Generator</code>) generates a throwaway plugin on every run and typechecks, builds and integration-tests it, so the templates can&#39;t silently rot.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Describe what the plugin needs in <code>src/info.ts</code> (permissions, commands, config), declaring commands with <code>defineCommands</code>. See <a href="./plugin-info-and-readmes">Plugin info and READMEs</a>.</li><li>Add plugin-specific behavior in <code>src/plugin.ts</code>&#39;s <code>onPluginLoad</code> hook. The generated plugin extends <code>PluginBase</code> and calls <code>registerPlugin</code>, which provide shared metadata, lifecycle logging and the automatic update check. Read <a href="./building">Building</a> first: plugins run on QuickJS and a few API calls need workarounds. Follow <a href="./code-style">Code style</a>: public code needs JSDoc descriptions and <code>pnpm lint</code> checks it.</li><li>If the plugin needs settings, declare them as a schema with <code>@pumpkin-plugins/config</code> and add it as a dev dependency. See <a href="./plugin-config">Plugin config</a>.</li><li>Run <code>pnpm exec turbo run build test:integration --filter=@pumpkin-plugins/&lt;folder&gt;</code> to build the plugin and load it on a real server.</li></ul><h3 id="files-and-network-access" tabindex="-1">Files and network access <a class="header-anchor" href="#files-and-network-access" aria-label="Permalink to &quot;Files and network access&quot;">​</a></h3><p>A plugin can&#39;t read files or open sockets unless its WIT world imports the WASI interfaces. Opt in per plugin in <code>package.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pumpkinPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;entry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/plugin.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build/my-plugin.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wasi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sockets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><p>The server also has to grant the matching permissions. <code>PluginBase</code> metadata includes the automatic updater permission; list other permissions in <code>info.permissions</code>:</p><table tabindex="0"><thead><tr><th>Capability</th><th>Permissions the plugin will typically request</th></tr></thead><tbody><tr><td><code>filesystem</code></td><td><code>fs.read.data</code>, <code>fs.write.data</code> (access is limited to the plugin&#39;s own data folder, preopened as <code>data</code>)</td></tr><tr><td><code>sockets</code></td><td><code>network.tcp.bind</code> to listen, <code>network.tcp.connect</code> to connect out</td></tr><tr><td><code>udp</code></td><td><code>network.udp.bind</code> to receive, <code>network.udp.outgoingdatagram</code> to send to any address, <code>network.udp.connect</code> to talk to one</td></tr><tr><td><code>http</code></td><td><code>http.outbound</code> to make HTTP or HTTPS requests; the automatic updater adds this permission</td></tr></tbody></table><h2 id="without-the-generator" tabindex="-1">Without the generator <a class="header-anchor" href="#without-the-generator" aria-label="Permalink to &quot;Without the generator&quot;">​</a></h2><p>Copy <code>packages/bedrock-addon-manager</code> or generate a plugin and delete what you don&#39;t need. Three things are easy to forget:</p><ul><li>The plugin has to be registered for releases: an entry in <code>release-please-config.json</code> <strong>and</strong> one in <code>.release-please-manifest.json</code>, with the plugin at version <code>0.0.0</code>. The exact entries are in <a href="./ci-and-releases#registering-a-plugin-for-releases">Registering a plugin for releases</a>, and <code>node scripts/check-release-config.mjs</code> tells you what is missing.</li><li><code>pnpm install</code> has to run so the workspace links are created.</li><li><code>pnpm readme</code> has to run so the package table in the root README lists it.</li></ul>',19)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
